class CapsulePage extends HTMLElement {
    constructor() {
        super();
        this.capsuleTotal = window.capsuleTotal;
        this.capsuleJSON = window.capsuleJSON;
        this.productTypes = window.productTypes;
        this.addEventListener("change", this.onUpdate.bind(this));
        this.submitButton = this.querySelector(".capsule-submit");
        this.submitButton.addEventListener("click", this.formSubmit.bind(this));
        this.init();
    }
    init() {
        console.log(this.capsuleJSON);
        this.extraVariants();
    }
    allOptionsSelected(a = this) {
        const b = a.querySelectorAll(".product-option").length;
        a = a.querySelectorAll("input:checked").length;
        return b === a;
    }
    extraVariants() {
        this.querySelectorAll(".capsule__item").forEach((a) => {
            var b = a.getAttribute("data-extra-variants");
            if ("false" !== b) {
                var c = JSON.parse(a.getAttribute("data-json"));
                b = JSON.parse(b);
                c = c.concat(b);
                a.setAttribute("data-json", JSON.stringify(c));
                console.log(c);
            }
        });
    }
    updateImage(a, b) {
        JSON.parse(a.getAttribute("data-json")).forEach((c, e = !1) => {
            -1 !== c.options.indexOf(b) && !0 !== e && updateSrcSet(a.querySelector("img"), c.featured_image.src);
        });
    }
    onUpdate(a) {
        let b = a.target.closest(".capsule__item");
        var c = b.querySelectorAll("input:checked"),
            e = b.getAttribute("data-index");
        c = Array.from(c, (d) => d.value).join(", ");
        let f = b.querySelector('.product-option[data-option="Color"] input:checked');
        f && this.updateImage(b, f.value);
        this.updateOptions(a.target);
        b.querySelector(".capsule-item__selections").textContent = c;
        this.allOptionsSelected(b) &&
            ((a = this.getSelectedVariant(b)), (e = document.querySelector(`.selection[data-index="${e}"] .selection__variant`))) &&
            ((e.textContent = c), e.setAttribute("data-json", JSON.stringify({ id: a.id, price: a.price })), e.classList.add("selected"));
    }
    getSelectedVariant(a) {
        const b = a.querySelectorAll("input:checked");
        if (b) {
            var c = Array.from(b, (f) => f.value).join(" / "),
                e = !1;
            JSON.parse(a.dataset.json).forEach((f) => {
                f.title === c && (e = f);
            });
            return e;
        }
    }
    updateOptions(a) {
        const b = a.closest(".capsule__item"),
            c = a.closest(".product-option").dataset.optionIndex,
            e = a.value,
            f = JSON.parse(b.dataset.json);
        b.querySelectorAll(".product-option").forEach((d) => {
            1 != d.dataset.totalOptions &&
                (d.dataset.optionIndex == c
                    ? d.querySelectorAll("input").forEach((g) => {
                          g.disabled = !1;
                      })
                    : f.forEach((g) => {
                          g.options[c] === e && (d.querySelector(`input[value='${g.options[d.dataset.optionIndex]}']`).disabled = !g.available);
                      }));
        });
        this.submitButton.disabled = this.allOptionsSelected() ? !1 : !0;
    }
    formSubmit() {
        const a = Array.from(document.querySelectorAll(".selection__variant.selected"));
        let b = [];
        const c = "bundle_" + Math.floor(Date.now() / 1e3),
            e = window.bundleId,
            f = document.querySelector("cart-drawer");
        a.forEach((d) => {
            d = { quantity: 1, id: JSON.parse(d.getAttribute("data-json")).id, properties: { _bundle: e, _bundle_total: this.capsuleTotal, bundle_id: c } };
            b.push(d);
        });
        fetch("/cart/add.js", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ items: b, sections: "cart-drawer,cart-icon-bubble,main-cart-items,main-cart-footer", sections_url: window.location.pathname }),
        })
            .then((d) => d.json())
            .then((d) => {
                f.renderContents(d);
                f.classList.contains("active") || f.open();
            })
            .catch((d) => {
                console.error("Error:", d);
            });
    }
}
customElements.define("capsule-page", CapsulePage);
